unitsize(1 cm);

pair A, B, C, D;

A = (0, 0);

B = (10, 0);

C = (10, 10);

D = (0, 5);

draw(A--B--C--D--cycle);

label("$A$", A, NW);

label("$B$", B, NE);

label("$C$", C, N);

label("$D$", D, SE);

draw(rightanglemark(A, C, D));

[/asy]

